import{_ as s}from"./chunks/a15d060d981993bb.ByJl2EP_.js";import{_ as a,o as t,c as i,a6 as n}from"./chunks/framework.B8j4beN0.js";const k=JSON.parse('{"title":"Contexts: Module, Submodule and Feature","description":"How Feluqa resolves the current context (module, submodule, feature) so that code never repeats it, and how each context scopes permissions, storage and configuration.","frontmatter":{"sidebarTitle":"Contexts","icon":"blocks","title":"Contexts: Module, Submodule and Feature","description":"How Feluqa resolves the current context (module, submodule, feature) so that code never repeats it, and how each context scopes permissions, storage and configuration.","summary":"Explains how Feluqa derives a code context from its Module, Submodule, and Feature location so names and resources can be scoped without repeating full paths. It describes each level, name resolution and context-derived resources, with examples of the hierarchy and the boundaries each context controls.","date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","weight":2,"status":"Target","tags":["feluqa","module","submodule","feature","context"],"draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"}},"headers":[],"relativePath":"get-started/directory-structure/module-submodule-feature-contexts.md","filePath":"get-started/directory-structure/module-submodule-feature-contexts.md"}'),l={name:"get-started/directory-structure/module-submodule-feature-contexts.md"};function o(r,e,d,p,u,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="contexts-module-submodule-and-feature" tabindex="-1">Contexts: Module, Submodule and Feature <a class="header-anchor" href="#contexts-module-submodule-and-feature" aria-label="Permalink to &quot;Contexts: Module, Submodule and Feature&quot;">​</a></h1><p>The scanner always knows <strong>where a piece of code lives</strong>. That location is its <em>context</em>. Code never repeats its context: inside the <code>sales</code> module you write <code>Refund</code>, not <code>sales.refund</code>.</p><h2 id="the-context-chain" tabindex="-1">The context chain <a class="header-anchor" href="#the-context-chain" aria-label="Permalink to &quot;The context chain&quot;">​</a></h2><p><img src="'+s+`" alt="Mermaid diagram"></p><table tabindex="0"><thead><tr><th>Context</th><th>Defined by</th><th>Scopes</th><th>Runtime toggle</th></tr></thead><tbody><tr><td><strong>Product</strong></td><td><code>feluqa.toml</code> marker</td><td>Which modules are assembled and deployed</td><td>Install / upgrade</td></tr><tr><td><strong>Module</strong></td><td>Folder <code>src/modules/&lt;id&gt;/</code></td><td>Permissions, roles, storage path, config prefix, migrations</td><td>Enable / disable per product</td></tr><tr><td><strong>Submodule</strong></td><td>Folder <code>src/modules/&lt;id&gt;/submodules/&lt;sub&gt;/</code></td><td>A sub-domain with its own resources and permissions, sharing the module&#39;s lifecycle</td><td>Follows its module</td></tr><tr><td><strong>Feature</strong></td><td><code>#[feluqa::feature]</code></td><td>A capability inside a module or submodule</td><td>Per license, per tenant, or per environment</td></tr><tr><td><strong>Panel</strong></td><td><code>#[feluqa::panel]</code></td><td>A web surface; resources attach themselves to it</td><td>Per product</td></tr><tr><td><strong>Tenant</strong></td><td>Runtime</td><td>Data and user isolation</td><td>Created and archived at runtime</td></tr></tbody></table><h2 id="module" tabindex="-1">Module <a class="header-anchor" href="#module" aria-label="Permalink to &quot;Module&quot;">​</a></h2><p>A module needs nothing: the folder <code>modules/sales/</code> is enough (id = <code>sales</code>, version = the one in <code>Cargo.toml</code>). A <code>module.rs</code> file exists only to declare dependencies.</p><div class="language-rust vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">feluqa</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">module!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { requires </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;core &gt;= 1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Layout:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/modules/sales/</span></span>
<span class="line"><span>├── permissions.rs          # custom business permissions only</span></span>
<span class="line"><span>├── roles.rs                # optional: explicit roles</span></span>
<span class="line"><span>├── models/customer.rs</span></span>
<span class="line"><span>├── services/refunds.rs     # business logic + #[gate]</span></span>
<span class="line"><span>├── resources/customer.rs   # form + table + actions + policy</span></span>
<span class="line"><span>├── features/loyalty.rs     # optional features</span></span>
<span class="line"><span>└── submodules/</span></span>
<span class="line"><span>    └── invoicing/</span></span>
<span class="line"><span>        ├── permissions.rs</span></span>
<span class="line"><span>        ├── services/</span></span>
<span class="line"><span>        └── resources/invoice.rs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h2 id="submodule" tabindex="-1">Submodule <a class="header-anchor" href="#submodule" aria-label="Permalink to &quot;Submodule&quot;">​</a></h2><p>A submodule is a <strong>sub-domain</strong> that deserves its own permissions and resources but not its own lifecycle. It has the same internal layout as a module and:</p><ul><li>inherits the module&#39;s dependencies, storage root and configuration prefix;</li><li>adds one segment to every name: <code>sales.invoicing.refund</code>;</li><li>is installed, enabled, disabled and removed <strong>with its module</strong>;</li><li>cannot be depended upon by another module directly; it exposes its API through its parent.</li></ul><p>Use a submodule when two areas share data and lifecycle but need separate access control. Use a separate module when they could be installed independently.</p><h2 id="feature" tabindex="-1">Feature <a class="header-anchor" href="#feature" aria-label="Permalink to &quot;Feature&quot;">​</a></h2><p>A feature is a <strong>named, switchable capability</strong> inside a module or submodule. Code is always compiled in; the feature decides whether it is <em>active</em>.</p><div class="language-rust vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// src/modules/sales/features/loyalty.rs</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/// Customer loyalty points and tiers.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/// Enabled only on licenses that include &quot;loyalty&quot;.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">#[feluqa</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">feature(id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;loyalty&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, default </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> false)]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Loyalty</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Gating by feature:</p><div class="language-rust vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/// Grants loyalty points after a paid order.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">#[feluqa</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gate(require_feature </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Loyalty</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, require_permission </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GrantPoints</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grant_points</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Ctx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, order</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OrderId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;()&gt; { </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* ... */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Rules:</p><ul><li>A disabled feature hides its resources, navigation entries and routes (404, not 403), and its permissions disappear from role editors.</li><li>Disabling a feature <strong>never deletes data</strong>. Data stays under the module&#39;s storage path until an explicit purge.</li><li>Feature state is stored in SQLite and changed from the System panel or the CLI, never by editing TOML.</li><li>A feature may depend on another feature of the same module: <code>#[feluqa::feature(id = &quot;tiers&quot;, requires = [&quot;loyalty&quot;])]</code>.</li></ul><h2 id="name-resolution" tabindex="-1">Name resolution <a class="header-anchor" href="#name-resolution" aria-label="Permalink to &quot;Name resolution&quot;">​</a></h2><p>Names are built at compile time from the context chain.</p><table tabindex="0"><thead><tr><th>Written in code</th><th>Context</th><th>Full name</th></tr></thead><tbody><tr><td><code>Refund</code></td><td>module <code>sales</code></td><td><code>sales.refund</code></td></tr><tr><td><code>Refund</code></td><td>submodule <code>sales/invoicing</code></td><td><code>sales.invoicing.refund</code></td></tr><tr><td><code>Customer</code> resource, <code>delete</code></td><td>module <code>sales</code></td><td><code>sales.customers.delete</code></td></tr><tr><td><code>billing::Invoice</code></td><td>any other module</td><td><code>billing.invoice</code></td></tr><tr><td><code>platform::ManageModules</code></td><td>anywhere</td><td><code>platform.manage_modules</code></td></tr></tbody></table><p>Argument resolution in <code>#[gate]</code> follows a fixed order and produces a compile error with a suggestion when nothing matches:</p><ol><li>a capability of the enclosing resource (<code>view_any</code>, <code>delete</code>, ...);</li><li>a permission of the current submodule, then of the current module;</li><li>a permission of another module, with an explicit path;</li><li>a platform permission.</li></ol><h2 id="context-derived-resources" tabindex="-1">Context-derived resources <a class="header-anchor" href="#context-derived-resources" aria-label="Permalink to &quot;Context-derived resources&quot;">​</a></h2><p>The scanner derives the following from the context, so none are written by hand:</p><ul><li>storage directory: <code>&lt;product-or-platform&gt;/storage/modules/&lt;module-id&gt;[/&lt;submodule&gt;]</code>;</li><li>configuration prefix and environment variable names: <code>SALES_...</code>, <code>SALES_INVOICING_...</code>;</li><li>migration namespace;</li><li>audit-log scope.</li></ul><p>The platform loader confirms the module id at runtime; the scanner provides it at compile time. <strong>They must match, otherwise the module is rejected.</strong> A crate with no module owner is an error, never a guess.</p>`,30)])])}const g=a(l,[["render",o]]);export{k as __pageData,g as default};
